console.log(result);
`,solutionCode:`// output: [width, height] launches a whole grid of threads.
const gpu = new GPU({ mode });

const board = gpu.createKernel(function () {
  return (this.thread.x + this.thread.y) % 2;
}, {
  output: [8, 8],
});

const result = board();
console.log(result);
